#define _GNU_SOURCE
#include <ctype.h>
#include <sys/types.h>
#include <unistd.h>

/*
 * Audit-container compatibility shim for Lean's /proc/<getpid()>/exe lookup.
 * /proc/self resolves in the procfs PID namespace and therefore yields the
 * host-visible PID even when getpid() yields a nested-namespace PID.
 */
pid_t getpid(void) {
    char target[64];
    ssize_t size = readlink("/proc/self", target, sizeof(target) - 1);
    if (size <= 0) {
        return (pid_t)1;
    }
    target[size] = '\0';
    pid_t result = 0;
    for (ssize_t index = 0; index < size; ++index) {
        if (!isdigit((unsigned char)target[index])) {
            return (pid_t)1;
        }
        result = result * 10 + (target[index] - '0');
    }
    return result > 0 ? result : (pid_t)1;
}

